insert into public.schools (id, name, foundation, ownership, is_university, categories, curricula, province, city, district, address, latitude, longitude, website, origin, archived, notes) values
  ('dpk-ummul-quro-depok-islamic-school', 'Ummu’l Quro Depok Islamic School', null, 'swasta', false, array['Swasta','Islamic']::text[], array['kurikulum nasional-Agama (as stated for SDIT)']::text[], 'Jawa Barat', 'Kota Depok', 'Beji', 'Jl. M.H. Sanim No.16, Kukusan, Kecamatan Beji (per KalderaNews 2023; Mommies Daily 2021 writes ''Jl. Mandor Sanim, Kukusan Beji, Depok'')', null, null, 'https://ummulqurodepok.sch.id/', 'seed', false, 'Nama lengkap di sumber: Ummu’l Quro Depok Islamic School (TKIT, SDIT, SMPIT Ummu''l Quro Depok). 2027/2028 figures are the list ''Biaya PMB'' before wave discounts. Official discount table (deducted from Biaya PMB) - TK: Gel I Sep-Des 2026 internal 2.000.000 / umum 1.000.000 / jamaah haji umrah UQ 1.500.000; Gel II Jan-Jul 2027 1.000.000 / - / 500.000. SD: Gel I 3.500.000 / 1.500.000 / 2.000.000; Gel II 1.500.000 / - / 500.000. SMP: Gel I 5.000.000 / 3.000.000 / 3.500.000; Gel II 3.000.000 / 1.500.000 / 2.000.000. Extra Rp1.000.000 off for full early payment of Biaya PMB. Historical records (2022/2023 SD from Mommies Daily; 2024/2025-inferred SMP from KalderaNews) are secondary sources; the 2022/2023 ''uang pangkal'' is a wave-dependent price, so compare with 2027/2028 list price with care. Address not shown in extracted official page text.'),
  ('dpk-sekolah-islam-terpadu-insan-mandiri-depok', 'Sekolah Islam Terpadu Insan Mandiri Depok', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', 'Limo', 'Komplek Diamond Golden Cinere No. 17B, Jln. Krukut Raya Kel. Grogol, Kec. Limo, Depok', null, null, 'https://insanmandiridepok.sch.id/', 'seed', false, 'Nama lengkap di sumber: Sekolah Islam Terpadu Insan Mandiri Depok (PGIT/TKIT/SDIT Insan Mandiri Cinere-Depok). Registration allowed with 40% of total invest; 60% by July before classes start. Extra discounts on sarpras: 25% for TKIT IMCD continuers, 15% DGC residents, 5% siblings; 100% free for orphans living in Asrama Yatim Insan Mandiri (after survey). Fee table is a screenshot of a Google document (''Opera Snapshot 2026-08-18'').'),
  ('dpk-nurul-fikri-islamic-school', 'Nurul Fikri Islamic School', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', 'Cimanggis', 'Jl. Tugu Raya No.61, Tugu, Cimanggis, Depok - Jawa Barat', null, null, 'https://ppdb.nurulfikri.sch.id/', 'seed', false, 'Nama lengkap di sumber: Nurul Fikri Islamic School (SIT Nurul Fikri: TKIT/SDIT/SMPIT/SMAIT Nurul Fikri). Official 2027/2028 page: early full-payment discount on Dana Pengembangan if paid by 31 Okt / 30 Nov / 31 Des 2026: TK 4.000.000 / 3.000.000 / 2.000.000; SD, SMP, SMA 4.000.000 / 2.000.000 / 1.500.000. Registration fee for applicants from NF: TK 400.000, SD 500.000, SMP 550.000, SMA 550.000. Add-ons for students needing further support: assessment Rp 500.000; SPP bulanan Kategori A +Rp 200.000, Kategori B +Rp 700.000; therapy Rp 150.000/session. SPP excludes catering and transport. Historical 2021/22 and 2022/23 ''uang pangkal'' figures (Mommies Daily) appear to bundle components that the 2027/28 page splits (Dana Pengembangan + Dana Pendidikan + seragam), so compare totals, not line items. The 2026/2027 SD record comes from Popmama (news media), not the school.'),
  ('dpk-smait-raflesia', 'SMAIT Raflesia', 'Yayasan Raflesia', 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', 'Cimanggis', 'Komp. Pondok Duta 1, Jl. Mahkota Raya No.32B / Jl. H Saman Rt.10/08 Kel. Tugu, Cimanggis - Depok 16451', null, null, 'http://smait.raflesia.sch.id/', 'seed', false, 'Source total ''JUMLAH 8.200.000''. Page: ''*Note : Belum Termasuk Uang Kegiatan Tahunan dan Buku (dapat ditanyakan langsung ke sekolah)''. Foundation name taken from the sister SMK Raflesia brochure (''Murid aktif Yayasan Raflesia''); the SMAIT page itself only says ''Sekretariat Yayasan''.'),
  ('dpk-smk-raflesia-depok', 'SMK Raflesia Depok', 'Yayasan Raflesia', 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', null, null, null, null, 'http://www.smkraflesiadepok.sch.id/', 'seed', false, 'Vocational school (programs: Layanan Kesehatan/keperawatan; Pengembangan Perangkat Lunak dan Gim). Listed as ''SMK Islam Raflesia'' in the SMAIT Raflesia unit menu. Official lunas discounts: Gel 1 (s/d 31 Jan 2027) Rp600.000; Gel 2 (1 Feb-30 Apr 2027) Rp350.000; Gel 3 (1 Mei-31 Jul 2027) Rp200.000; family of active Yayasan Raflesia pupils Rp250.000; neighbours RW.08/RW.14 Rp100.000; SMPIT Raflesia 2026/2027 graduates Rp2.000.000 (until 31 Des 2026). Address not found on the page.'),
  ('dpk-sekolah-cakra-buana', 'Sekolah Cakra Buana', null, 'swasta', false, array['Swasta','Nasional']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', 'Pancoran Mas', 'Jl. Raya Sawangan No.91, Mampang, Kec. Pancoran Mas, Kota Depok, Jawa Barat 16433', null, null, 'https://cakrabuanaschool.sch.id/', 'seed', false, 'Image uploaded 2026/03 (per file path); marked ''LIMITED TIME ONLY''. Formulir fee Rp 900.000 is a single footnote, assumed by the brochure layout to apply to all levels. Category ''Nasional'' is a label choice (no religious affiliation stated); curriculum not verified. KalderaNews (Nov 2023) lists an ''SMP Cakra Buana'' at Jl. KH. Abdurrahman, Pondok Jaya, Cipayung (site cakrabuana.sch.id, unreachable); its relation to this school is unverified, so those figures are not included.'),
  ('dpk-pondok-pesantren-modern-nurussalam-smp-sma-moder', 'Pondok Pesantren Modern Nurussalam (SMP - SMA) Modern Islamic Boarding School', null, 'swasta', false, array['Swasta','Islamic','Boarding']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', 'Sawangan', 'Jalan Madrasah No. 86 Kp. Panggulan Pengasinan Sawangan Kota Depok', null, null, 'https://www.nurussalam86.sch.id/', 'seed', false, 'Year labelling is inconsistent in the source: page title says 2026/2027 (and mentions ''biaya masuk santri baru tahun 2026'', ''Regular Gel. 3 (April s/d Juni 2026)'', ''gratis SPP bulan Juli 2026''), the URL slug says 20252026, the regular fee image carries no year, and the separate ''jalur prestasi'' image is titled ''BIAYA MASUK SANTRI BARU 2025 / 2026''. Recorded as 2026/2027 per page title. Columns in verbatims are ''SMP | SMA''. Entry fees payable min 50% after acceptance, in up to 3 instalments (50/25/25).'),
  ('dpk-smait-pesantren-nururrahman', 'SMAIT Pesantren Nururrahman', null, 'swasta', false, array['Swasta','Islamic','Boarding']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', 'Pancoran Mas', 'Jl. Raya Sawangan No.Km.2. No.11, Pancoran Mas, Depok, Jabar 16436', null, null, 'https://smaitpnr.sch.id/', 'seed', false, 'Source total ''TOTAL BIAYA SISWA REGULER Rp 16.502.500*'' (= formulir + pangkal + 1 month SPP + kesiswaan + air minum; excludes asrama). ''* Biaya belum termasuk buku dan seragam''. Whether boarding is compulsory is not stated; ''Boarding'' category reflects the pesantren name and asrama fee.'),
  ('dpk-sd-alam-kampung-sawah-depok', 'SD Alam Kampung Sawah Depok', 'Yayasan Sahabat Istimewa Indonesia', 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', 'Cilodong', 'Jl. SMPN 6 Kalibaru, Kav Bni D6 No.7, Kalibaru, Cilodong, Depok City, Jawa Barat 16412 (per Popmama 2026)', null, null, 'https://sekolahalamkampungsawah.id/', 'seed', false, 'Nama lengkap di sumber: SD Alam Kampung Sawah Depok (Sekolah Alam Kampung Sawah). Nature school (sekolah alam), inclusive. Official 2026-2027 brochure found is for the INKLUSI class only (total 21.500.000). The 2026/2027 regular-class figures come from Popmama (news media), which does not say which class type it covers; they differ from the inklusi brochure and are close to the official 2025-2026 regular brochure (total 18,500,000), so they likely refer to the regular class - unverified. Down payment Rp5.000.000 after MoU; balance cash or max 3 instalments. ''Islamic'' category is based on ''Infak''/''Buku Sahabat Qur''an'' wording, not an explicit statement. Address is from Popmama, not the school.'),
  ('dpk-sekolah-islam-dian-didaktika', 'Sekolah Islam Dian Didaktika', null, 'swasta', false, array['Swasta','Islamic','Cambridge']::text[], array['Kurikulum Nasional','Cambridge (SD, SMP per leaflet)']::text[], 'Jawa Barat', 'Kota Depok', 'Cinere', 'Jl. Rajawali Blok F No. 16 Cinere, Depok, Jawa Barat. Kode Pos : 16512', null, null, 'https://www.diandidaktika.sch.id/', 'seed', false, 'Nama lengkap di sumber: Sekolah Islam Dian Didaktika (SD/SMP/SMA Islam Dian Didaktika). SD/SMP leaflets state ''Kurikulum Nasional dan Cambridge''; SMA leaflet states ''Kurikulum Nasional''. Popmama (10 Feb 2026) reproduces the same SD figures, corroborating the leaflet.'),
  ('dpk-smp-tahfizhpreneur-cq', 'SMP Tahfizhpreneur CQ', 'Yayasan Islam Cahaya Qur''an', 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', 'Sukmajaya', 'Jl. H. Dimun Raya (Gg. Merah delima), Kp. Sidamukti 01/01 Sukmajaya - Depok', null, null, 'https://smp.cahayaquran.sch.id/', 'seed', false, 'Nama lengkap di sumber: SMP Tahfizhpreneur CQ (Cahaya Qur''an). Amounts written in shorthand on the page (e.g. ''7,5jt'', ''1850k'', ''850k''); converted to Rupiah without rounding. Pupils with (potential) special needs must provide a shadow teacher. Same foundation as SDIT Cahaya Quran (separate record).'),
  ('dpk-ar-rahman-islamic-school-cinere', 'Ar-Rahman Islamic School Cinere', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', 'Cinere', 'Jl. Bukit Cinere Raya No.15C Cinere, Gandul, Depok (per Popmama)', null, null, 'https://arrahman-islamic.sch.id/', 'seed', false, 'Only source is Popmama (news media, ''estimasi'', compiled from various sources). School website appeared in search results but was not opened.'),
  ('dpk-lazuardi-al-falah-depok', 'Lazuardi Al-Falah Depok', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', null, 'Kompleks LIA Depok, Jl. Margonda Raya No. 200, Depok (per Popmama; Mommies Daily 2021 gives the same)', null, null, 'https://depok.lazuardialfalah.sch.id/', 'seed', false, 'Nama lengkap di sumber: Lazuardi Al-Falah Depok (SD Lazuardi Al Falah). Inclusive school (quota 2 per class per Mommies Daily 2021). 2026/2027 estimate excludes ABK assistance, extracurriculars, transport, catering and end-of-year show. No official fee page found (FAQ has no amounts).'),
  ('dpk-sit-darul-abidin', 'SIT Darul Abidin', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', 'Beji', 'Jl. Karet Hijau No.52, Beji Tim, Kecamatan Beji, Kota Depok, Jawa Barat 16422 (SD, per Popmama); SMPIT: Jl. Karet Hijau No.23, Beji Tim. (per KalderaNews)', null, null, 'https://ppdb.darulabidin.sch.id/', 'seed', false, 'Nama lengkap di sumber: SIT Darul Abidin (SDIT / SMPIT Darul Abidin). No official fee page reachable (ppdb.darulabidin.sch.id / .com fee URLs returned 404). All figures are secondary sources.'),
  ('dpk-semut-semut-the-natural-school', 'Semut-Semut The Natural School', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', 'Cimanggis', 'Jl. Industri Kapal Dalam No. 25A RTM, Kelapa Dua, Cimanggis, Depok (per Popmama)', null, null, 'https://semut-semut.sch.id/', 'seed', false, 'Nama lengkap di sumber: Semut-Semut The Natural School (SD Semut-Semut). Nature school; inclusive (per Mommies Daily 2021); Mommies Daily calls it ''salah satu SD Islam di Depok''. 2026/2027 estimate excludes catering, transport, extracurriculars. School website SD page has no fee info.'),
  ('dpk-sekolah-karakter-cimanggis', 'Sekolah Karakter Cimanggis', 'Indonesia Heritage Foundation (IHF) - per Mommies Daily naming', 'swasta', false, array['Swasta','Nasional']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', 'Cimanggis', 'Jl. Raya Jakarta Bogor Km. 31 No. 46, Cimanggis, Depok (per Popmama; Mommies Daily 2021: ''Jl. Raya Jakarta Bogor Km31 No.46, Cimanggis Depok'')', null, null, null, 'seed', false, 'Nama lengkap di sumber: Sekolah Karakter Cimanggis (SD Karakter IHF - Indonesia Heritage Foundation). Same address in both sources, so treated as the same school. 2026/2027 uang pangkal (25.0M) is lower than 2021/2022 (29.1M) while an annual activity fee (6.5M) is listed separately in 2026/2027 - fee structure probably changed; do not compute inflation from uang pangkal alone. ''Nasional'' is a label choice (character-education school; no religious affiliation stated).'),
  ('dpk-sekolah-pribadi-depok', 'Sekolah Pribadi Depok', null, 'swasta', false, array['Swasta','Nasional Plus','Cambridge']::text[], array['Cambridge (Checkpoint test included in ''perlengkapan'' per Popmama)']::text[], 'Jawa Barat', 'Kota Depok', null, 'Jl. Margonda Raya No. 229, Depok, Jawa Barat (per Popmama; Mommies Daily 2021 gives the same)', null, null, 'https://pribadidepok.sch.id/', 'seed', false, 'Nama lengkap di sumber: Sekolah Pribadi Depok (Pribadi Bilingual School / SD Pribadi). CAUTION: the school does not publish fees (official FAQ: ''Untuk informasi biaya pendidikan silahkan untuk menanyakan secara langsung pada pihak admission''). Figures are unverified media estimates. A search-engine summary (not a page we opened) attributed identical 2026 figures (Rp1.500.000 / Rp53.000.000 / Rp69.850.000 per year) to a different school (''Lentera Kasih''); treat the attribution with extra caution.'),
  ('dpk-sdit-cahaya-quran-depok', 'SDIT Cahaya Quran Depok', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', 'Cilodong', 'Jl. Merah Delima No.11, Sukemaju, Kec. Cilodong, Kota Depok, Jawa Barat 16415 (per Popmama)', null, null, 'https://cahayaquran.sch.id/', 'seed', false, 'Only source is Popmama (news media). Likely the same foundation as SMP Tahfizhpreneur CQ (Yayasan Islam Cahaya Qur''an) but not confirmed by an opened source; kept as a separate record.'),
  ('dpk-sd-islam-al-haraki', 'SD Islam Al-Haraki', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', 'Pancoran Mas', 'Jl. Belimbing 3 No.1-2, Depok, Kec. Pancoran Mas, Kota Depok, Jawa Barat 16431 (per Mommies Daily 2020)', null, null, 'https://alharaki.sch.id/', 'seed', false, 'Nama lengkap di sumber: SD Islam Al-Haraki (SIT Al Haraki). OLD DATA ONLY (2021/2022). Official site (alharaki.sch.id, incl. FAQ/PSB pages) blocked automated access (Cloudflare 403 for curl and WebFetch), so current fees could not be captured. Levels per the site''s PSB page titles in search results (KB/TK, SD, SMP, SMA).'),
  ('dpk-kinderfield-primary-school', 'Kinderfield Primary School', null, 'swasta', false, array['Swasta','International','Cambridge']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', null, 'Jl. Mentengan Raya No.72, Kemiri Muka, Depok (per Mommies Daily 2020)', null, null, null, 'seed', false, 'Nama lengkap di sumber: Kinderfield Primary School (Depok). OLD DATA ONLY (2021/2022). ''International/Cambridge'' category is based on depok24jam.com (25/08/2026) describing ''Kinderfield Highfield School Depok'' as an international (Cambridge) school; that article''s fee numbers were not used (explicitly cross-year 2023-2026 estimates) and it gives a different address (Jl. Margonda Raya No. 229), so the campus/branding link is unverified. No official Depok fee source found.'),
  ('bgr-sekolah-pelita-harapan-sph-sentul-city', 'Sekolah Pelita Harapan (SPH) Sentul City', null, 'swasta', false, array['Swasta','International','IB','Kristen','Boarding']::text[], array['IB Primary Years Programme (PYP)','IB Middle Years Programme (MYP)','IB Diploma Programme (DP)']::text[], 'Jawa Barat', 'Kabupaten Bogor', null, null, null, null, 'https://sph.edu', 'seed', false, 'Fee tables on sph.edu are campus tabs rendered by JavaScript (Framer). Static HTML only contains the default Lippo Village tab; the Sentul City figures were extracted from the page''s own JS module (https://framerusercontent.com/sites/7L1moI0VPfdXxFQB7ZpJQM/xZd6uJevG.0E0Tbc57.mjs) by resolving the ''Sentul City'' tab variant (desktop, tablet and mobile layouts agree except the 6-year DPP). Verbatim strings are the variant''s cell texts joined with '' | ''. YEAR LABEL CONFLICT: the English page heads these tables ''2027/2028'', while the Indonesian page (https://sph.edu/id/pendaftaran/biaya) shows the same figures under ''2026/2027'' headings. Recorded as 2027/2028 per the English page; treat the year as uncertain until confirmed with the school. Old URL sph.edu/id/pendaftaran/biaya/biaya-sekolah-sph-sentul-city/ now returns 404. Kabupaten Bogor assignment based on Sentul City location; no street …'),
  ('bgr-sma-dwiwarna-boarding-school', 'SMA Dwiwarna Boarding School', null, 'swasta', false, array['Swasta','Boarding','Islamic']::text[], array['Nasional (Merdeka)','Keagamaan (Tahfidz/Tahsin)','Internasional (Cambridge/Goethe)']::text[], 'Jawa Barat', 'Kabupaten Bogor', null, 'Jl. Raya Parung Km. 40 Bogor, Jawa Barat, Indonesia 16330', null, null, 'https://www.smadwiwarna.sch.id', 'seed', false, 'Official school blog post dated 2024-10-19 (article:modified_time 2026-09-24); body states ''tahun ajaran 2026/2027'' and ''Pendaftaran Tahun Ajaran 2027/2028 SUDAH DIBUKA'', so these may be the 2026/2027 figures still shown during 2027/2028 admissions. School''s own 3-year estimate: Rp335.000.000 (UP 60jt + 36 x 7,5jt + seragam 5jt). City/postcode inferred from address (Jl. Raya Parung, 16330); kecamatan not stated.'),
  ('bgr-sdit-anak-shalih-bogor', 'SDIT Anak Shalih Bogor', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Bogor', null, 'Jl. Anak Shalih No.1, Cimahpar, Kota Bogor 16155', null, null, 'https://anakshalihbogor.sch.id', 'seed', false, '2026/2027 record from the school''s own PMB page (WordPress page date 2025-11-03, modified 2025-11-18). 2026/2027 official totals: laki-laki 21.050.000, perempuan 21.250.000. 2025/2026 record is from a news article citing the school website (historical, for fee-growth). SPP rose 1.350.000 -> 1.400.000.'),
  ('bgr-tkit-anak-shalih', 'TKIT Anak Shalih', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Bogor', null, null, null, null, 'https://anakshalihbogor.sch.id', 'seed', false, 'Same website/operator as SDIT Anak Shalih Bogor. Page totals: KB L 4.000.000 / P 4.050.000; TK L 4.300.000 / P 4.400.000. Street address of the TKIT campus not explicitly stated on the page (site footer lists ''Jl. Anak Shalih, Kel. Cimahpar, Bogor 16155'' among unit addresses); Kota Bogor assignment rests on that footer - verify.'),
  ('bgr-pondok-pesantren-darurrahmah-yapida', 'Pondok Pesantren Darurrahmah Yapida', null, 'swasta', false, array['Swasta','Boarding','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kabupaten Bogor', 'Gunungputri', 'Jl. KH Tb Asep Basri Kp. Sanding Desa. Bojong Nangka Kec. Gunungputri Kab.Bogor - Jawa Barat', null, null, 'https://daarurrahmah.com', 'seed', false, 'Page says ''Rincian lengkap investasi pendidikan untuk Tahun Ajaran 2026/2027'' and ''Update terakhir: Maret 2026'' (published_date left null because only month precision is given). Stated package totals: SMP/MTs Putra IDR 7.550.000; SMP/MTs Putri IDR 7.950.000; SMA Putra IDR 7.550.000; SMA Putri IDR 8.150.000. DISCREPANCY: SMA Putra components sum to 7.750.000, not the stated 7.550.000 (other three totals reconcile). ''Yapida'' appears in the school''s name on the page; foundation not stated. Page links to a separate ''Rincian Biaya Lengkap'' document that was not opened.'),
  ('bgr-pesantren-al-andalus', 'Pesantren Al-Andalus', 'Yayasan Darul Iman Wattaqwa Bogor', 'swasta', false, array['Swasta','Boarding','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kabupaten Bogor', 'Sukamakmur (putra) / Jonggol (putri)', 'Putra: Jl. Raya Menteng, KM. 13 RT.03/04, Dusun Cijuray, Desa Sukadami, Kec. Sukamakmur, Kab. Bogor. Putri: Jl. Raya Menteng KM. 6 Dusun Kadupandak, Desa Balekambang, Kec. Jonggol, Kab. Bogor.', null, null, 'https://pesantren-alandalus.com', 'seed', false, 'Nama lengkap di sumber: Pesantren Al-Andalus (Al-Andalus International Islamic Boarding School). Admission page (WordPress, modified 2026-09-07) is for new students TA 2027-2028: SMP IT (putra & putri) and I''dad Lughawiy (1-year Arabic prep before SMA IT). Fee schedule is not differentiated between the two programs. Foundation name taken from the bank-account holder shown for fee payments. A Pikiran Rakyat article on the 2025/2026 fees exists but returned HTTP 403 (not used).'),
  ('bgr-sd-permata-islam-cibinong', 'SD Permata Islam Cibinong', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kabupaten Bogor', 'Cibinong', 'Jl. Jantung Harapan RT 08 RW 07 Kel. Pabuaran Kec. Cibinong Kab. Bogor Jawa Barat 16916', null, null, null, 'seed', false, 'News article (Medcom.id, 25 Feb 2026, by Bramcov Stivens Situmeang) that says it quotes the school''s own website/Instagram; official page not opened by us. The article headline is TA 2026/2027, but the Permata Islam section itself does not restate the year (hence academic_year_inferred=true).'),
  ('bgr-sdit-al-madinah-cibinong', 'SDIT Al-Madinah Cibinong', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kabupaten Bogor', 'Cibinong', 'Jl. Raya Sukahati No.36, Karadenan, Kec. Cibinong, Kab. Bogor, Jawa Barat 16913', null, null, 'https://pmbsit.almadinabogor.sch.id', 'seed', false, 'News article (Medcom.id, 25 Feb 2026, by Bramcov Stivens Situmeang) that says it quotes the school''s own website/Instagram; official page not opened by us. Article cites pmbsit.almadinabogor.sch.id (our connection to it failed). Stated total Rp24.740.000, but listed items sum to Rp24.665.000 (Rp75.000 gap; an item may be missing). Early-observation subsidies: to 30 Sep Rp5.000.000 (total Rp19.740.000), to 31 Oct Rp4.000.000, to 30 Nov Rp3.000.000, to 31 Dec Rp2.500.000.'),
  ('bgr-sdit-al-fath-cibinong', 'SDIT Al-Fath Cibinong', null, 'swasta', false, array['Swasta','Islamic']::text[], array['Kurikulum Nasional','Cambridge English Test program']::text[], 'Jawa Barat', 'Kabupaten Bogor', 'Cibinong', 'Jl. Raya Cikaret No.1, Harapan Jaya, Kec. Cibinong, Kab. Bogor, Jawa Barat 16914', null, null, 'https://alfathschoolindonesia.sch.id', 'seed', false, 'News article (Medcom.id, 25 Feb 2026, by Bramcov Stivens Situmeang) that says it quotes the school''s own website/Instagram; official page not opened by us. Article cites alfathschoolindonesia.sch.id. Fees reportedly include field trips.'),
  ('bgr-sd-islam-anugerah-insani-cibinong', 'SD Islam Anugerah Insani Cibinong', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kabupaten Bogor', 'Cibinong', 'Blok LC Acropolis, Jl. Bojong Depok Baru III No.19, Karadenan, Kec. Cibinong, Kab. Bogor, Jawa Barat 16913', null, null, null, 'seed', false, 'News article (Medcom.id, 25 Feb 2026, by Bramcov Stivens Situmeang) that says it quotes the school''s own website/Instagram; official page not opened by us. Article explicitly says these are Tahun Pelajaran 2024/2025 figures taken from Instagram @sdianugerahinsaniofficial (secondary citation of social media). Stated total Rp24.350.000 equals the sum excluding the Rp300.000 form fee. Books not included; instalments possible.'),
  ('bgr-sdit-al-hidayah-cibinong', 'SDIT Al-Hidayah Cibinong', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kabupaten Bogor', 'Cibinong', 'Jl. KSR Dadi Kusmayadi, RT.02/RW.05, Tengah, Kec. Cibinong, Kab. Bogor, Jawa Barat 16914', null, null, 'https://sekolahalhidayah.com', 'seed', false, 'News article (Medcom.id, 25 Feb 2026, by Bramcov Stivens Situmeang) that says it quotes the school''s own website/Instagram; official page not opened by us. Article cites sekolahalhidayah.com (our connection to it failed). Total Uang Pangkal Rp17.150.000 for both putra and putri; "Tersedia diskon Rp2.000.000 (ketentuan berlaku)".'),
  ('bgr-smk-wikrama-bogor', 'SMK Wikrama Bogor', null, 'swasta', false, array['Swasta','Nasional']::text[], '{}'::text[], 'Jawa Barat', 'Kota Bogor', 'Bogor Timur', 'Jl. Raya Wangun Kelurahan Sindangsari Bogor Timur 16720', null, null, 'https://smkwikrama.sch.id', 'seed', false, 'Historical (TP 2025-2026) official news post; the current SPMB 2026-2027 site (spmb.smkwikrama.sch.id) shows no fees. Postcode 16720 copied as printed on the site (unusual for Kota Bogor).'),
  ('bgr-sekolah-alam-bogor', 'Sekolah Alam Bogor', null, 'swasta', false, array['Swasta','Sekolah Alam']::text[], '{}'::text[], 'Jawa Barat', 'Kota Bogor', 'Bogor Utara', 'Jalan Pangeran Ash-Shogiri No.150 Bogor Utara, Jawa Barat', null, null, 'https://sekolahalambogor.sch.id', 'seed', false, 'All four brochures (JPEG images on Google Drive) are linked from the official admission page under ''Biaya Pendidikan Tahun Ajaran 2027/2028''; images downloaded and transcribed manually (no OCR cross-check). Brochure totals (''Total Biaya Pendidikan 1 s.d 7'', which include one month SPP): PG 17.250.000, TK A 16.250.000, TK B 14.250.000; SD 32.400.000 (non-graduate) / 29.900.000 (graduate); SM 31.950.000 / 29.950.000; SMX 36.050.000 (non-SM) / 34.050.000 (SM graduate). All brochure totals reconcile with their items. Payments are staged (Joining Fee, Tahap 1, Tahap 2/Pelunasan). Level mapping is ours: ''Sekolah Menengah (SM)'' -> SMP and ''SMX School of Maker'' -> SMA (SMX brochure distinguishes ''Lulusan SM''); formal SMP/SMA status not stated. Inclusion (Inklusi) and SM Plus PSQ variants exist with higher SPP.'),
  ('bgr-smas-insan-kamil-bogor', 'SMAS Insan Kamil Bogor', 'Yayasan Pendidikan Insan Kamil Bogor', 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Bogor', 'Bogor Barat', 'Jalan Aria Surialaga Pasir Jaya Bogor barat', null, null, 'https://www.smainsankamil.sch.id', 'seed', false, '2026/2027 from the official PDF (JUMLAH per wave: Rp 9.950.000 / 10.950.000 / 11.950.000). 2025/2026 from Disway news citing the school website (totals Gel. 1 Rp9.700.000, Gel. 2 Rp10.700.000, Gel. 3 Rp11.700.000). Disway describes the program as non-mukim (not boarding) and calls the school ''SMA Insan Kamil (Ma''had Al Ihya)''.'),
  ('bgr-sma-kosgoro-bogor', 'SMA Kosgoro Bogor', 'Yayasan Dharma Setia Kosgoro', 'swasta', false, array['Swasta','Nasional']::text[], '{}'::text[], 'Jawa Barat', 'Kota Bogor', null, 'Jl. Raya Pajajaran No. 217 A, Bogor, Jawa Barat', null, null, 'https://sma-kosgoro.sch.id', 'seed', false, '2027/2028 brochure totals: Gel. I Rp 9.200.000,- ; Gel. II Rp 11.200.000,-. DISCREPANCY: Gel. II items sum to 10.200.000, not the printed 11.200.000 (Gel. I reconciles). 2025/2026 (Disway news citing school website): Gel. 1 Rp8.280.000; Gel. 2 Rp9.530.000 (both reconcile with items).'),
  ('bgr-sdit-aliya', 'SDIT Aliya', 'Yayasan Himma ''Aliya', 'swasta', false, array['Swasta','Islamic']::text[], array['Kurikulum Merdeka','Metode Ummi (Al-Qur''an)']::text[], 'Jawa Barat', 'Kota Bogor', 'Bogor Barat', 'Jalan Gardu Raya RT.03/RW.11 Kel. Bubulak Kec. Bogor Barat, Kota Bogor 16115', null, null, 'https://sitaliya.sch.id', 'seed', false, '2025/2026 figures from Disway news (cites the school website); uniforms not included (''Biaya belum termasuk seragam''). 2027/2028 year inferred: homepage PPDB schedule runs 1-30 Oktober 2026 and requires age 6 by 1 Juli 2027, but no academic-year label is printed. The official homepage contains injected spam text (site possibly compromised) - treat with caution. Foundation name from homepage greeting ''Yayasan Himma ''Aliya dan SIT Aliya''.'),
  ('bgr-sdit-al-ikhlas', 'SDIT Al Ikhlas', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kota Bogor', 'Tanah Sareal', 'Kompleks Masjid Al-Ikhlas, Tamansari Persada, Cibadak, Tanah Sareal', null, null, null, 'seed', false, 'Disway news (2025-06-20) citing the school website. Stated total ''Biaya Pendidikan'' Laki-laki Rp15.700.000 / Perempuan Rp16.100.000 (termasuk biaya masuk, SPP Juli, seragam, kegiatan, dan buku); kegiatan and buku are not itemised (implied ~Rp2.050.000, not recorded as a component).'),
  ('bgr-sdit-ummul-quro-bogor', 'SDIT Ummul Quro Bogor', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kabupaten Bogor', 'Kemang', 'Jl. KH. Sholeh Iskandar No.1, Parakan Jaya, Kemang', null, null, 'https://ppdb.ummulqurobogor.sch.id', 'seed', false, 'Disway news (2025-06-20) citing the school website; ''Biaya dibayarkan bertahap sesuai tahapan masuk.'' Kabupaten Bogor assignment inferred from ''Parakan Jaya, Kemang'' in the address (Kemang is a kecamatan of Kabupaten Bogor).'),
  ('bgr-sdit-al-kautsar-klapanunggal', 'SDIT Al Kautsar Klapanunggal', null, 'swasta', false, array['Swasta','Islamic']::text[], '{}'::text[], 'Jawa Barat', 'Kabupaten Bogor', 'Klapanunggal', null, null, null, null, 'seed', false, 'Disway news (2025-06-20) citing the school website. Located ''di kawasan Klapanunggal'' (no street address given).'),
  ('univ-ui', 'Universitas Indonesia', null, 'negeri', true, array['Negeri']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', null, 'Kampus UI, Depok 16424 (as shown for SIMAK UI office)', null, null, 'https://www.ui.ac.id (admissions: https://simak.ui.ac.id)', 'seed', false, 'Status: negeri (PTN-BH). Lokasi di sumber riset: Kota Depok. UKT group (1-11 in 2025/2026 and 2026/2027) is assigned per student based on the paying capacity of whoever finances the student; a non-subsidised middle/upper-income family should plan for the programme''s top group (e.g. Pendidikan Dokter UKT 11 = Rp20.000.000/semester; Ilmu Komputer UKT 9 = Rp14.600.000). SNBP/SNBT pay UKT only; Jalur Mandiri pays the same UKT table plus a one-time IPI whose tier follows the UKT group (IPI 1 for UKT 1-2 = Rp0 up to IPI 4 for UKT 9-11, e.g. Rp120.000.000 for Pendidikan Dokter). KKI (international class) pays a flat UKT plus IPI. Faculty left null: the decrees/articles list programmes only. Overseas-status registration: Rp1.100.000/semester (reguler/mandiri), Rp2.475.000/semester (KKI). Trend: for the five sampled S1 programmes, 2025/2026 UKT (Kompas, citing SK 681/2025) and 2025/2026 IPI (SK 688/2025) equal the 2026/2027 values; 2024/2025 (Kontan) used 5 groups whose top amounts were close to today''s top groups (e.g. Manajemen Rp14.650.000 in 2024 vs Rp14.600.000 in 2025/2026 and 2026/2027), so the restructuring mainly added lower/middle groups rather than raising the ceiling.'),
  ('univ-ipb', 'IPB University (Institut Pertanian Bogor)', null, 'negeri', true, array['Negeri']::text[], '{}'::text[], 'Jawa Barat', 'Kabupaten Bogor', null, 'Jl. Raya Dramaga, Kampus IPB Dramaga Bogor 16680 (as shown in admisi.ipb.ac.id footer)', null, null, 'https://admisi.ipb.ac.id', 'seed', false, 'Status: negeri (PTN-BH). Lokasi di sumber riset: Bogor (Dramaga campus). S1 UKT uses groups I-VIII (most programmes I-VII; Kedokteran I-VI), assigned by the economic capacity of parents/guardians. The same UKT applies to SNBP, SNBT and Seleksi Mandiri; SM-IPB entrants additionally pay a one-time BPIF in three tiers (the page does not say how the tier is chosen). Plan-for figures: Kedokteran top UKT Rp20.000.000/semester + BPIF Rp135.000.000-150.000.000 (mandiri); Agribisnis top UKT Rp10.000.000 + BPIF Rp63.000.000-70.000.000. Trend: sampled UKT (2024/2025 Kompas) and BPIF (2024 via IDN Times) are identical to the 2026 official figures. Kerjasama/BUD and Kelas Internasional pay a flat UKT (heading says ''Tahun 2025'') plus a larger BPIF.'),
  ('univ-ug', 'Universitas Gunadarma', null, 'swasta', true, array['Swasta']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', null, null, null, null, 'https://www.gunadarma.ac.id (admissions: https://pendaftaran.gunadarma.ac.id, ppmb.gunadarma.ac.id)', 'seed', false, 'Status: swasta. Lokasi di sumber riset: Kota Depok (per research brief; not stated in the opened sources). Private fee model: one-time USP (uang gedung) by admission grade AA/A/B + BPP each semester + a per-SKS charge. Official admission hosts could not be read (ppmb: proxy 502/private-IP; pendaftaran: Cloudflare 403; baak: 403), so only secondary sources are used; they disagree for Sistem Komputer. Treat all Gunadarma figures as [Low confidence]; this needs verification. Address not captured from an opened source.'),
  ('univ-pnj', 'Politeknik Negeri Jakarta', null, 'negeri', true, array['Negeri']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', null, 'Jalan Prof. DR. G.A. Siwabessy, Kampus UI, Depok 16425', null, null, 'http://www.pnj.ac.id (admissions: https://penerimaan.pnj.ac.id)', 'seed', false, 'Status: negeri (PTN-BLU; per decree ''Instansi Pemerintah Yang Menerapkan Pola Pengelolaan Keuangan Badan Layanan Umum''). Lokasi di sumber riset: Kota Depok. UKT groups 1-8 (+KIP). Mandiri entrants are placed only in UKT VI-VIII and pay a one-time IPI (Rp12.500.000 or Rp10.500.000 in sampled programmes). Amounts come from official decree annexes that list per-candidate assignments (personal data omitted), not from a published tariff table; the PNJ admissions HTML pages returned 403. For every sampled programme, the UKT 6-8 amounts observed for SNBT 2025/2026 equal those in the 2026/2027 mandiri decree (different tracks, so this is indicative, not a same-track comparison).'),
  ('univ-upnvj', 'Universitas Pembangunan Nasional "Veteran" Jakarta', null, 'negeri', true, array['Negeri']::text[], '{}'::text[], 'Jawa Barat', 'Kota Depok', null, null, null, null, 'https://penmaru.upnvj.ac.id (admissions; returned 403 to automated fetch)', 'seed', false, 'Status: negeri. Lokasi di sumber riset: Kota Depok (Limo campus, per research brief; not verified in this research). SNBP/SNBT: 8 UKT groups. Mandiri (SEMA): one flat UKT - in every sampled programme it equals the SNBP/SNBT top group (Kelompok 8) - plus a one-time IPI in three payment groups. Only news sources (detik; Kontan crediting PENMARU UPNVJ) could be read. Both list S1 Ilmu Politik''s top UKT as the unusual ''Rp 6.202.000'' - recorded as published, may be a typo upstream. Faculty names and campus address not captured from opened sources.'),
  ('univ-unida', 'Universitas Djuanda', null, 'swasta', true, array['Swasta']::text[], '{}'::text[], 'Jawa Barat', 'Kabupaten Bogor', null, 'Jl. Tol Ciawi No 1 Bogor 16720, Jawa Barat (as printed on the brochure ''Sekretariat PMB'')', null, null, 'https://unida.ac.id (PMB: https://pmb.unida.ac.id)', 'seed', false, 'Status: swasta. Lokasi di sumber riset: Bogor (Ciawi). Private flat-fee model: one-time Pendaftaran + Prakuliah + SPS (uang gedung), then a fixed SPP per semester that already includes SKS, UTS and UAS (praktikum extra). Brochure: ''Angsuran Pertama minimal: Rp. 5.000.000,-''; wave badges show 50%/30%/20%/10% (badge fine print not fully legible; the top-left tag reads ''Beasiswa SPS 50% di Gelombang Perdana''). Figures transcribed from an image - [Medium confidence] in transcription; re-check against the brochure before publishing.'),
  ('univ-uika', 'Universitas Ibn Khaldun Bogor', null, 'swasta', true, array['Swasta']::text[], '{}'::text[], 'Jawa Barat', 'Kota Bogor', null, null, null, null, 'http://uika-bogor.ac.id (PMB: https://siakad.uika-bogor.ac.id/spmbfront/)', 'seed', false, 'Status: swasta (Yayasan Pendidikan Islam Ibn Khaldun Bogor). Lokasi di sumber riset: Bogor (per research brief and the decree''s ''Bogor'' dateline). New-student schedule for Kelas Reguler: SPP Rp2.500.000 per semester for all sampled programmes, plus semester-I SKS/UAS charges (20 SKS), a two-instalment DSP (Rp4.000.000-4.500.000 per instalment in sampled programmes), and small one-off items. spmb.uika-bogor.ac.id/biaya-kuliah failed TLS verification (incomplete certificate chain; not bypassed) and WebFetch got 503; the same schedule was found as an image on the official siakad PMB portal. Transcribed from an image - [Medium confidence] in transcription, although every sampled row sums to its printed total.'),
  ('univ-unhan-ri', 'Universitas Pertahanan Republik Indonesia', null, 'negeri', true, array['Negeri']::text[], '{}'::text[], 'Jawa Barat', 'Kabupaten Bogor', null, 'Komplek Indonesia Peace and Security Center (IPSC) Sentul, Kabupaten Bogor, Jawa Barat (as stated in Kompas photo caption)', null, null, 'https://penerimaan.idu.ac.id (PMB; not reachable from this environment)', 'seed', false, 'Status: kedinasan (under Kementerian Pertahanan). Lokasi di sumber riset: Kabupaten Bogor (Sentul). Tuition-free cadet programme; graduates may become TNI officers (''bisa jadi perwira TNI dengan pangkat Letda''). A search-engine summary mentioned a minimum 10-year service bond - search_snippet_only, not verified. Not a fee-planning case except for living/incidental costs.'),
  ('univ-unpak', 'Universitas Pakuan', null, 'swasta', true, array['Swasta']::text[], '{}'::text[], 'Jawa Barat', 'Kota Bogor', null, null, null, null, 'https://pmb.unpak.ac.id', 'seed', false, 'Status: swasta. Lokasi di sumber riset: Bogor (per research brief; not verified). Belum ada data biaya terverifikasi (lihat catatan riset). NO FEE DATA: pmb.unpak.ac.id and manajemen.unpak.ac.id/biaya-pendidikan return a ''Security Check | Universitas Pakuan'' page (HTTP 403) to curl and WebFetch. Search results offered only third-party aggregator/blog pages (kelaskaryawan, stekom wiki, harga.web.id, etc.), which were not used. This needs verification directly with UNPAK.'),
  ('univ-tazkia', 'Universitas Tazkia (formerly Institut Agama Islam Tazkia)', null, 'swasta', true, array['Swasta']::text[], '{}'::text[], 'Jawa Barat', 'Kabupaten Bogor', null, 'Kampus Alif: Jl. Ir. H. Djuanda No. 78 Sentul, Citaringgul, Kec. Babakan Madang, Kota Bogor, Jawa Barat 16810 (as printed on beasiswa.tazkia.ac.id)', null, null, 'https://tazkia.ac.id', 'seed', false, 'Status: swasta. Lokasi di sumber riset: Bogor (Sentul). Belum ada data biaya terverifikasi (lihat catatan riset). NO FEE DATA: the official SPMB category page (news.tazkia.ac.id/snbt?id=28&view=category) lists only 2023 items; the official ''Tabel Biaya Tazkia 2022/2023'' article returned 404; beasiswa.tazkia.ac.id/berapa-tahun-kuliah-s1 contains no amounts. The name change to Universitas Tazkia (2025) comes from a search-engine summary only - not verified. The address was read on beasiswa.tazkia.ac.id (page title ''SPMB - Institut Tazkia'').')
